const item = $input.item;
const j = item.json;

const binaryKeys = Object.keys(item.binary || {});
if (binaryKeys.length === 0) {
  throw new Error('لم يتم استلام أي ملف. تأكد من رفع تسجيل صوتي أو مرئي في النموذج.');
}
const bin = item.binary[binaryKeys[0]];
const mimeType = (bin.mimeType || '').toLowerCase();
const isVideo = mimeType.startsWith('video/');

return {
  json: {
    speakerName: j['اسم المتحدث'] || '',
    speechType: j['نوع الخطاب'] || '',
    topic: j['موضوع الخطاب (إن وجد)'] || 'غير محدد',
    notes: j['ملاحظات إضافية'] || 'لا يوجد',
    isVideo,
    inputMode: isVideo ? 'video' : 'audio',
    inputModeLabel: isVideo ? 'فيديو (المسار الحالي يحلّل الصوت فقط)' : 'صوت فقط',
    detectedMimeType: mimeType,
  },
  binary: {
    file: bin,
  },
};

const j = $input.item.json;
const raw = j.content ?? j.text ?? j.output_text ?? j.response ?? (typeof j === 'string' ? j : JSON.stringify(j));

let parsed;
try {
  const cleaned = String(raw).trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { parse_error: e.message, raw_text: String(raw) };
}

const src = $('تجهيز الملف').item.json;
const transcriptJson = $('OpenAI - تفريغ النص').item.json;
const transcript = transcriptJson.text ?? transcriptJson.content ?? transcriptJson.transcript ?? '';

return {
  json: {
    speakerName: src.speakerName,
    speechType: src.speechType,
    topic: src.topic,
    notes: src.notes,
    inputMode: src.inputMode,
    inputModeLabel: src.inputModeLabel,
    detectedMimeType: src.detectedMimeType,
    transcript,
    analysis: parsed,
  },
};

