const genJ = $input.item.json;
const raw = genJ.content ?? genJ.text ?? genJ.output_text ?? genJ.response ?? (typeof genJ === 'string' ? genJ : JSON.stringify(genJ));

let finalReport;
try {
  const cleaned = String(raw).trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  finalReport = JSON.parse(cleaned);
} catch (e) {
  finalReport = {
    full_report: String(raw),
    strengths: '',
    improvements: '',
    style_signature: '',
  };
}

const src = $('دمج نتائج التحليل').item.json;

return {
  json: {
    speaker_name: src.speakerName,
    speech_type: src.speechType,
    topic: src.topic,
    input_mode: src.inputMode,
    detected_mime_type: src.detectedMimeType,
    transcript: src.transcript || null,
    verbal_analysis: (src.analysis && src.analysis.verbal) || src.analysis || {},
    nonverbal_analysis: (src.analysis && src.analysis.nonverbal) || null,
    style_signature: finalReport.style_signature || '',
    strengths: finalReport.strengths || '',
    improvements: finalReport.improvements || '',
    full_report: finalReport.full_report || String(raw),
    notes: src.notes,
  },
};

